import{_ as e,c as a,o as l,ae as n}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Table Background Color Customizing","description":"Table Background Color Customizing","frontmatter":{"title":"Table Background Color Customizing","description":"Table Background Color Customizing"},"headers":[],"relativePath":"guide/drag-drop-settings/table-background-color-customizing-ninja-tables-drag-and-drop.md","filePath":"guide/drag-drop-settings/table-background-color-customizing-ninja-tables-drag-and-drop.md"}'),r={name:"guide/drag-drop-settings/table-background-color-customizing-ninja-tables-drag-and-drop.md"};function t(c,o,d,i,s,g){return l(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="table-background-color-customizing" tabindex="-1">Table Background Color Customizing <a class="header-anchor" href="#table-background-color-customizing" aria-label="Permalink to &quot;Table Background Color Customizing&quot;">​</a></h1><p>To make a table look smarter, you can use colors on both texts and cells. Color customizing the table header, rows, columns, or cells makes the table appear more engaging. In this document, we will learn how to color WordPress tables in the Ninja Tables Drag &amp; Drop mode.</p><h2 id="change-table-background-color" tabindex="-1"><strong>Change Table Background</strong> <strong>Color</strong> <a class="header-anchor" href="#change-table-background-color" aria-label="Permalink to &quot;**Change Table Background** **Color**&quot;">​</a></h2><p>To manage colors for the header, rows, columns, and specific cells, first go to &quot;Background&quot; by clicking on the button above the table. Again, when we are done coloring cells, headers, rows, or columns, we can exit from the Background Mode by clicking on the Close button from the leftmost side of the Table Editor. Click “Save Table” to save the changes.</p><h3 id="general-color-options" tabindex="-1">General Color Options <a class="header-anchor" href="#general-color-options" aria-label="Permalink to &quot;General Color Options&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Table-background-color-1024x467.png" alt="Table background color"> This is where the basic table coloring happens. You&#39;ll see 3 options here-</p><ul><li>Header Background</li><li>Even Row Background</li><li>Odd Row Background</li></ul><h4 id="change-table-header-background-color" tabindex="-1"><strong>Change Table Header Background Color</strong> <a class="header-anchor" href="#change-table-header-background-color" aria-label="Permalink to &quot;**Change Table Header Background Color**&quot;">​</a></h4><p>Select a color from the “Header Background” option in the table editor on the left. Then the color of the First Row, which is by default the Header of the table, will be changed to your selected color. We have selected deep magenta already.</p><h4 id="change-even-row-background-color" tabindex="-1"><strong>Change Even Row Background Color</strong> <a class="header-anchor" href="#change-even-row-background-color" aria-label="Permalink to &quot;**Change Even Row Background Color**&quot;">​</a></h4><p>Select a color from the “Even Row Background” option and change it to whatever color you like to see to contrast or match the header.</p><h4 id="change-odd-row-background-color" tabindex="-1"><strong>Change Odd Row Background Color</strong> <a class="header-anchor" href="#change-odd-row-background-color" aria-label="Permalink to &quot;**Change Odd Row Background Color**&quot;">​</a></h4><p>Likewise, pick a color for the odd rows from the “Odd Row Background” option. Here&#39;s our table with a deep magenta header, a light pink even row, and white odd rows. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Table-row-color-odd-and-even-1024x481.png" alt="Table row color odd and even"></p><h3 id="selected-color-options" tabindex="-1">Selected Color Options <a class="header-anchor" href="#selected-color-options" aria-label="Permalink to &quot;Selected Color Options&quot;">​</a></h3><p>As soon as you select a cell, 3 more options will appear.</p><ul><li>Selected Cell Row Background</li><li>Selected Cell Column Background</li><li>Selected Cell Background <img src="https://ninjatables.com/wp-content/uploads/2023/08/Cell-background-color-1024x496.png" alt="Cell background color"></li></ul><h4 id="change-selected-cell-row-background-color" tabindex="-1"><strong>Change Selected Cell Row Background Color</strong> <a class="header-anchor" href="#change-selected-cell-row-background-color" aria-label="Permalink to &quot;**Change Selected Cell Row Background Color**&quot;">​</a></h4><p>Click on a cell to get the “Selected Color Options” on the left. This option will let you color the entire row the selected cell is in.</p><h4 id="change-selected-cell-column-background-color" tabindex="-1"><strong>Change Selected Cell Column Background Color</strong> <a class="header-anchor" href="#change-selected-cell-column-background-color" aria-label="Permalink to &quot;**Change Selected Cell Column Background Color**&quot;">​</a></h4><p>Following the same process, click on a cell to color the entire column the selected cell is in.</p><h4 id="change-selected-cell-background-color" tabindex="-1"><strong>Change Selected Cell Background Color</strong> <a class="header-anchor" href="#change-selected-cell-background-color" aria-label="Permalink to &quot;**Change Selected Cell Background Color**&quot;">​</a></h4><p>And finally, if you only want to color a specific cell, click the cell and then click “Selected Cell Background.” This does not change the color of the row/column you&#39;ve previously colored. Here&#39;s an example- <img src="https://ninjatables.com/wp-content/uploads/2023/08/selected-cell-in-tables-1024x509.png" alt="selected cell colors in table"></p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>You can quick-edit the table from the &quot;Background&quot; button at the top instead of moving to the &quot;Settings&quot; tab and looking for the Background editing option. Table background color customizing is easier than ever when it&#39;s Ninja Tables! Let us know your thoughts on this feature.</p>',24)])])}const b=e(r,[["render",t]]);export{u as __pageData,b as default};
